WITH Subquery1 AS ( SELECT t1.SUBJECT_CODE, t1.SUBJECT_CODE_DESC, t1.DEPARTMENT_NAME, t1.SCHOOL_NAME, t2.SUBJECT_TITLE, t2.NUM_ENROLLED_STUDENTS, ROW_NUMBER() OVER (PARTITION BY t1.DEPARTMENT_NAME ORDER BY t1.SUBJECT_CODE) AS window_column, t1.DEPARTMENT_CODE FROM SIS_SUBJECT_CODE t1 JOIN LIBRARY_SUBJECT_OFFERED t2 ON t1.COURSE_NUMBER = t2.COURSE_NUMBER WHERE t2.TERM_CODE = '2014FA' AND t2.NUM_ENROLLED_STUDENTS > 5 AND t1.DEPARTMENT_NAME = 'Mathematics' AND t1.DEPARTMENT_NAME = 'Mathematics' ), Subquery2 AS ( SELECT sd.DEPARTMENT_NAME, (STDDEV_SAMP(tso.NUM_ENROLLED_STUDENTS) / NULLIF(AVG(tso.NUM_ENROLLED_STUDENTS), 0)) AS coefficient_of_variation, sd.DEPARTMENT_CODE FROM SIS_DEPARTMENT sd JOIN TIP_SUBJECT_OFFERED tso ON sd.DEPARTMENT_CODE = tso.OFFER_DEPT_CODE WHERE sd.DEPARTMENT_NAME = 'Mathematics' GROUP BY sd.DEPARTMENT_NAME, sd.DEPARTMENT_CODE ) SELECT s1.SUBJECT_CODE, s1.SUBJECT_CODE_DESC, s1.DEPARTMENT_NAME, s1.SCHOOL_NAME, s1.SUBJECT_TITLE, s1.NUM_ENROLLED_STUDENTS, s1.window_column, s2.coefficient_of_variation FROM Subquery1 s1 JOIN Subquery2 s2 ON s1.DEPARTMENT_NAME = s2.DEPARTMENT_NAME AND s1.DEPARTMENT_CODE = s2.DEPARTMENT_CODE ORDER BY s1.SUBJECT_CODE